import{_ as t,o,c as a,ae as i}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"Best Practices for High-Conversion & Usable Forms (UX/UI)","description":"","frontmatter":{},"headers":[],"relativePath":"standards/usable_forms_best_practices.md","filePath":"standards/usable_forms_best_practices.md"}'),s={name:"standards/usable_forms_best_practices.md"};function r(n,e,l,c,u,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="best-practices-for-high-conversion-usable-forms-ux-ui" tabindex="-1">Best Practices for High-Conversion &amp; Usable Forms (UX/UI) <a class="header-anchor" href="#best-practices-for-high-conversion-usable-forms-ux-ui" aria-label="Permalink to &quot;Best Practices for High-Conversion &amp; Usable Forms (UX/UI)&quot;">​</a></h1><p>Use these guidelines as a system prompt or reference for generating and auditing the Authentication (Login/Signup) components.</p><h2 id="_1-design-input-structure" tabindex="-1">1. Design &amp; Input Structure <a class="header-anchor" href="#_1-design-input-structure" aria-label="Permalink to &quot;1. Design &amp; Input Structure&quot;">​</a></h2><ul><li><strong>Persistent Labels:</strong> Never use placeholders as the only label. Use <code>htmlFor</code> and <code>id</code> to link labels and inputs.</li><li><strong>Semantic Input Types:</strong> Use correct <code>type</code> attributes (<code>email</code>, <code>password</code>, <code>tel</code>) to trigger appropriate mobile keyboards.</li><li><strong>Visual Affordance:</strong> Match input width to expected content length.</li><li><strong>Password Visibility:</strong> Always include a &quot;show/hide&quot; toggle. Do NOT disable pasting (to allow Password Managers).</li></ul><h2 id="_2-progressive-validation-strategy" tabindex="-1">2. Progressive Validation Strategy <a class="header-anchor" href="#_2-progressive-validation-strategy" aria-label="Permalink to &quot;2. Progressive Validation Strategy&quot;">​</a></h2><ul><li><strong>Avoid &quot;Change&quot; Validation:</strong> Do not show errors while the user is still typing (too aggressive).</li><li><strong>&quot;On Blur&quot; Validation:</strong> Validate once the user leaves the field.</li><li><strong>Submit Validation:</strong> Re-validate all fields on form submission.</li><li><strong>Inline Errors:</strong> Display error messages near the field, not just at the top.</li></ul><h2 id="_3-feedback-error-communication" tabindex="-1">3. Feedback &amp; Error Communication <a class="header-anchor" href="#_3-feedback-error-communication" aria-label="Permalink to &quot;3. Feedback &amp; Error Communication&quot;">​</a></h2><ul><li><strong>Actionable Messages:</strong> Instead of &quot;Invalid input,&quot; use &quot;Email must include an @.&quot;</li><li><strong>Clear Buttons:</strong> Use Verb + Noun patterns (e.g., &quot;Create Account&quot; instead of &quot;Send&quot;).</li><li><strong>Clarity over Cleverness:</strong> Avoid blaming the user. Use helpful, neutral language.</li></ul><h2 id="_4-mobile-optimization-accessibility-wcag" tabindex="-1">4. Mobile Optimization &amp; Accessibility (WCAG) <a class="header-anchor" href="#_4-mobile-optimization-accessibility-wcag" aria-label="Permalink to &quot;4. Mobile Optimization &amp; Accessibility (WCAG)&quot;">​</a></h2><ul><li><strong>Touch Targets:</strong> Buttons and inputs must be at least 44x44px.</li><li><strong>Font Size:</strong> Minimum 16px for inputs to prevent automatic zoom on iOS.</li><li><strong>Keyboard Navigation:</strong> Ensure full <code>Tab</code> and <code>Enter</code> support. Maintain visible focus states (<code>:focus-visible</code>).</li><li><strong>Screen Readers:</strong> Use <code>aria-invalid=&quot;true&quot;</code> and <code>role=&quot;alert&quot;</code> for error messages.</li></ul><h2 id="_5-perceived-performance" tabindex="-1">5. Perceived Performance <a class="header-anchor" href="#_5-perceived-performance" aria-label="Permalink to &quot;5. Perceived Performance&quot;">​</a></h2><ul><li><strong>Double Submission Prevention:</strong> Disable the submit button immediately after the first click and show a loading state (spinner/text).</li><li><strong>Instant Feedback:</strong> Visual responses to interactions must occur within &lt;100ms.</li></ul>',12)])])}const p=t(s,[["render",r]]);export{m as __pageData,p as default};
